 function getElementByClassName(classnames){
   var objArray= new Array();  
   var i=0;  
   var tags=document.getElementsByTagName("input");
   while (i   tags.length){
       if(tags[i].className == classnames){
         if (tags[i].type == "radio"){
           if (!tags[i].checked ){
             tags[i].value="";
           }
         }
         objArray[objArray.length]=tags[i]
       } i++;
   }
   i=0;  
   tags=document.getElementsByTagName("select");
   while (i   tags.length){
       if(tags[i].className == classnames){
         objArray[objArray.length]=tags[i]
       }i++;
   }
   i=0;  
   tags=document.getElementsByTagName("textarea");
   while (i   tags.length){
       if(tags[i].className == classnames){
         objArray[objArray.length]=tags[i]
       }i++;
   }
   return objArray;
 }
function dotablerowAdd(sf) { 
 var prent = sf.parentNode; 
 while (prent.tagName != "TABLE"){
   prent = prent.parentNode;  
 }
 if (prent.tagName == "TABLE"){  
   var x= prent.insertRow(prent.rows.length-1);
   var vRow = prent.rows[1];
   var i = 0;
   var rowID = parseInt(prent.rows.length-1);
   while (i  vRow.cells.length) {
     var y=x.insertCell(i);   
     y.innerHTML = vRow.cells[i].innerHTML;
     y.style.cssText = vRow.cells[i].style.cssText;
     var ii = 0; 
     var inputs = y.getElementsByTagName("input");
     for (ii = 0; ii   inputs.length; ii++) { 
       inputs[ii].setAttribute("value","");
       inputs[ii].id = inputs[ii].id +"["+rowID + parseInt(i)+"]" ;
     }
     var inputs = y.getElementsByTagName("select");
     for (ii = 0; ii   inputs.length; ii++) { 
       inputs[ii].setAttribute("value","");
       inputs[ii].id = inputs[ii].id +"["+rowID + parseInt(i)+"]" ;
     }
     var inputs = y.getElementsByTagName("textarea");
     for (ii = 0; ii   inputs.length; ii++) { 
       inputs[ii].setAttribute("value","");
       inputs[ii].id = inputs[ii].id +"["+rowID + parseInt(i)+"]" ;
     }
     i++;
    } 
 } 
}
function dotablerowDel(sf){
 var prent = sf.parentNode; 
 while (prent.tagName != "TABLE")
 {
   prent = prent.parentNode;  
 }
 if (prent.tagName == "TABLE"){
   if (prent.rows.length  3){
     prent.deleteRow(prent.rows.length-2);
   }
 }
}
function selechange(elm){
